insert into public.flashcards (id, aula_id, ordem, frente, verso) values
  ('pass-a3-f01', 'pass-a3', 1, 'O que é o canabigerol (CBG)?', 'Fitocanabinoide não psicotrópico que atua como precursor de outros fitocanabinoides, inclusive do canabidiol (CBD).'),
  ('pass-a3-f02', 'pass-a3', 2, 'Dos três fitocanabinoides mais conhecidos (THC, CBD e CBG), qual é o único psicotrópico?', 'O tetra-hidrocanabinol (THC). Em dose muito alta num paciente suscetível, pode provocar surto psicótico.'),
  ('pass-a3-f03', 'pass-a3', 3, 'Qual é a proposta central do uso de fitocanabinoides no organismo?', 'A proposta não é cura de doenças, mas trazer equilíbrio e autorregulação (homeostase) ao sistema, atuando como suplementação.'),
  ('pass-a3-f04', 'pass-a3', 4, 'O que é o sistema endocanabinoide?', 'É um conjunto de receptores, ligantes endógenos e enzimas que atuam como sinalizadores entre as células. A professora pediu um asterisco neste slide.'),
  ('pass-a3-f05', 'pass-a3', 5, 'Qual é a principal função do sistema endocanabinoide no corpo?', 'Atuar como uma rede neurorreguladora que busca trazer regulação e homeostase ao sistema nervoso central, participando no ajuste fino cognitivo e fisiológico.'),
  ('pass-a3-f06', 'pass-a3', 6, 'O que significa dizer que os endocanabinoides são produzidos "sob demanda"?', 'Significa que eles não ficam armazenados em vesículas: são sintetizados e liberados exatamente quando e onde o corpo precisa deles.'),
  ('pass-a3-f07', 'pass-a3', 7, 'Cite três funções fisiológicas reguladas pelo sistema endocanabinoide.', 'Regulação do apetite, dor, ciclo sono-vigília, plasticidade sináptica, sistema imunológico e processos digestivos.'),
  ('pass-a3-f08', 'pass-a3', 8, 'Quais são os três grupos de componentes do sistema endocanabinoide?', 'Receptores (tipo 1 e tipo 2), ligantes do próprio corpo (anandamida e 2-AG) e enzimas de síntese e degradação. Ponto de prova.'),
  ('pass-a3-f09', 'pass-a3', 9, 'Quais são os dois principais endocanabinoides fabricados pelo organismo?', 'A anandamida e o 2-araquidonoilglicerol (2-AG). Ambos sintetizados sob demanda.'),
  ('pass-a3-f10', 'pass-a3', 10, 'Qual endocanabinoide é liberado na prática de atividade física?', 'A anandamida, chamada informalmente pela professora de "hormônio da felicidade e do bem-estar".'),
  ('pass-a3-f11', 'pass-a3', 11, 'O que é a sinalização retrógrada dos endocanabinoides?', 'É a transmissão em sentido inverso: sintetizados no pós-sináptico sob demanda, voltam à fenda e agem nos receptores do pré-sináptico, regulando outros neurotransmissores.'),
  ('pass-a3-f12', 'pass-a3', 12, 'Como a sinalização retrógrada evita uma crise de ansiedade no susto?', 'O excesso de glutamato faz o pós-sináptico produzir endocanabinoides, que voltam e ativam o receptor tipo 1 no pré-sináptico, freando a liberação de glutamato.'),
  ('pass-a3-f13', 'pass-a3', 13, 'Os endocanabinoides interagem com neurotransmissores além do glutamato?', 'Sim. O sistema endocanabinoide também interage com outras vias e receptores do sistema nervoso central, como os da serotonina.'),
  ('pass-a3-f14', 'pass-a3', 14, 'Qual a regra para não confundir a distribuição dos receptores tipo 1 e tipo 2?', 'Ambos estão espalhados pelo corpo todo: o que muda é onde cada um está mais concentrado. A professora marcou como importante para a prova.'),
  ('pass-a3-f15', 'pass-a3', 15, 'Onde predomina o receptor canabinoide tipo 1 (CB1)?', 'No sistema nervoso central (córtex pré-frontal, núcleos da base, hipocampo, hipotálamo) e na medula espinhal.'),
  ('pass-a3-f16', 'pass-a3', 16, 'Onde predomina o receptor canabinoide tipo 2 (CB2)?', 'Fora do sistema nervoso central, com destaque para o sistema imunológico, trato gastrointestinal e sistema nervoso periférico.'),
  ('pass-a3-f17', 'pass-a3', 17, 'Por que os fitocanabinoides têm excelente resposta no manejo da dor crônica?', 'Porque o receptor tipo 1 (CB1) está amplamente concentrado no sistema nervoso central e na medula espinhal.'),
  ('pass-a3-f18', 'pass-a3', 18, 'O que mostrou a metanálise com 68 pacientes sobre fitocanabinoides e TDAH?', 'Melhora em foco, concentração, motivação, redução de impulsividade, controle de ansiedade e qualidade do sono.'),
  ('pass-a3-f19', 'pass-a3', 19, 'No caso do paciente de 28 anos, por que o histórico de cannabis fumada foi relevante?', 'Como ele já usava cannabis fumada (que tem teor de THC muito maior que o óleo) sem surtos nem piora, o risco de psicose com o óleo é mínimo.'),
  ('pass-a3-f20', 'pass-a3', 20, 'Qual é a grande vantagem do óleo de fitocanabinoides em relação à cannabis fumada?', 'No óleo sabe-se exatamente a concentração, o teor de canabinoides e a dosagem em gotas ou miligramas.'),
  ('pass-a3-f21', 'pass-a3', 21, 'No caso do paciente de 28 anos, qual a suspeita sobre o diagnóstico prévio de "borderline"?', 'Pode ser um transtorno afetivo bipolar oculto. A pista clínica são as tentativas prévias de suicídio motivadas por impulsividade.'),
  ('pass-a3-f22', 'pass-a3', 22, 'Por que o THC pode ser perigoso se o paciente tiver um transtorno bipolar oculto?', 'Porque pode provocar uma virada maníaca e agravar crises de ansiedade.'),
  ('pass-a3-f23', 'pass-a3', 23, 'O que deve ser investigado na família de um paciente psiquiátrico antes de prescrever fitocanabinoides?', 'Histórico de esquizofrenia, transtorno bipolar, comportamentos dos pais e medicamentos de saúde mental em uso na família.'),
  ('pass-a3-f24', 'pass-a3', 24, 'Quais condições clínicas gerais contraindicam ou exigem grande cautela com fitocanabinoides?', 'Uso de varfarina (interação medicamentosa), cardiopatias e hipertensão arterial descompensada.'),
  ('pass-a3-f25', 'pass-a3', 25, 'O que diz o Código de Ética Médica sobre prescrever fitocanabinoides em casos refratários?', 'O médico deve agir com o melhor de sua capacidade em benefício da saúde humana, respaldando o uso em pacientes graves refratários aos tratamentos comuns.'),
  ('pass-a3-f26', 'pass-a3', 26, 'Qual era o marco regulatório anterior da Anvisa para venda em farmácias, e qual resolução o substituiu em 2026?', 'A Resolução RDC 327/2019, que foi substituída pela Resolução RDC 1.015/2026.'),
  ('pass-a3-f27', 'pass-a3', 27, 'Qual é a situação atual da Resolução 2.324/2022 do CFM sobre cannabis?', 'Foi suspensa. Não há hoje resolução do CFM limitando a prescrição, cabendo ao médico a autonomia e a responsabilidade clínica.'),
  ('pass-a3-f28', 'pass-a3', 28, 'Por que prescrever fitocanabinoides pelo SUS pode levar à judicialização?', 'Porque os produtos têm alto custo e não estão nas listas oficiais de medicamentos essenciais (RENAME ou REMUME).'),
  ('pass-a3-f29', 'pass-a3', 29, 'Em que data foram aprovadas as quatro resoluções da Anvisa sobre cultivo e regulação de cannabis em 2026?', 'Em 28 de janeiro de 2026, por unanimidade, cumprindo decisão do Superior Tribunal de Justiça (STJ). Ponto de prova.'),
  ('pass-a3-f30', 'pass-a3', 30, 'O que estabelece a Resolução RDC 1.012/2026 da Anvisa?', 'Autoriza o cultivo de cannabis exclusivamente para pesquisa científica, sem qualquer teto de THC.'),
  ('pass-a3-f31', 'pass-a3', 31, 'O que estabelece a Resolução RDC 1.013/2026 da Anvisa?', 'Autoriza o cultivo para produção medicinal (farmácias), com teto de THC de até 0,3% e autorização especial rigorosa.'),
  ('pass-a3-f32', 'pass-a3', 32, 'O que estabelece a Resolução RDC 1.014/2026 da Anvisa?', 'Cria um ambiente regulatório experimental (sandbox) para testar de forma controlada atividades com cannabis medicinal, contemplando associações.'),
  ('pass-a3-f33', 'pass-a3', 33, 'O que estabelece a Resolução RDC 1.015/2026 da Anvisa?', 'Define critérios de autorização sanitária para fabricação, importação e comercialização de produtos em farmácias (substituiu a RDC 327/2019).'),
  ('pass-a3-f34', 'pass-a3', 34, 'Qual é o teto de THC permitido no cultivo para fins medicinais pela RDC 1.013/2026?', 'Até 0,3% de THC. Acima disso, cultivo é restrito à pesquisa científica (RDC 1.012/2026).'),
  ('pass-a3-f35', 'pass-a3', 35, 'Qual tipo de receita é exigida para produtos de cannabis com até 0,2% de THC?', 'Receita de Controle Especial (branca em duas vias), sempre acompanhada de CID e justificativa.'),
  ('pass-a3-f36', 'pass-a3', 36, 'Qual tipo de receita é exigida para produtos de cannabis com mais de 0,2% de THC?', 'Receita amarela (Notificação de Receita A), acompanhada de receita com posologia, CID e justificativa.'),
  ('pass-a3-f37', 'pass-a3', 37, 'No caso de fibromialgia (mulher de 55 anos), por que foram pedidos exames do fígado (transaminases)?', 'Porque os fitocanabinoides e os remédios da paciente são metabolizados no fígado pelas enzimas do citocromo P450.'),
  ('pass-a3-f38', 'pass-a3', 38, 'Qual a proporção de canabinoides escolhida no óleo para a paciente com fibromialgia?', 'Óleo 1:1 (metade CBD e metade THC), aproveitando o efeito entourage para economizar gotas e reduzir efeitos adversos.'),
  ('pass-a3-f39', 'pass-a3', 39, 'Qual é a regra prática para divisão da dose diária quando o óleo contém THC?', '1/3 da dose pela manhã e 2/3 à noite, para evitar sonolência durante o dia e induzir/reparar o sono à noite.'),
  ('pass-a3-f40', 'pass-a3', 40, 'Quais são as referências teóricas mínimas de doses de CBD e THC para controle da dor?', 'Pelo menos 40 mg de canabidiol (CBD) e 15 mg de tetra-hidrocanabinol (THC).'),
  ('pass-a3-f41', 'pass-a3', 41, 'Com qual quantidade de THC a paciente do caso de fibromialgia já obteve controle da dor?', 'Com cerca de 5 mg de THC (dose bem abaixo da referência teórica de 15 mg).'),
  ('pass-a3-f42', 'pass-a3', 42, 'Qual foi a ordem de desprescrição dos medicamentos no caso de fibromialgia?', 'Primeiro a ciclobenzaprina; depois a duloxetina; e por último, redução da dose da pregabalina.'),
  ('pass-a3-f43', 'pass-a3', 43, 'Por que os fitocanabinoides são muito procurados por pacientes com dor crônica em uso de opioides?', 'Para auxiliar no desmame e substituição dos opioides, que geram dependência química e tolerância rapidamente.'),
  ('pass-a3-f44', 'pass-a3', 44, 'Segundo a Dra. Gisielli, qual é a etapa mais importante antes de prescrever fitocanabinoides?', 'Uma boa anamnese, avaliando histórico psiquiátrico pessoal e familiar, medicamentos em uso e contraindicações clínicas.')
